INSERT INTO subclasses (id, class_id, name, description, flavor_text, selection_level, created_at) VALUES ('thief', 'rogue', 'Thief', 'A master of stealth and larceny with fast hands', 'You hone your skills in the larcenous arts, learning tricks to enhance your agility and stealth.', 3, '2025-09-12 07:46:32');
INSERT INTO subclasses (id, class_id, name, description, flavor_text, selection_level, created_at) VALUES ('assassin', 'rogue', 'Assassin', 'A deadly killer who strikes from the shadows', 'You focus your training on the grim art of death, becoming a master of poison, disguise, and stealth.', 3, '2025-09-12 07:46:32');
INSERT INTO subclasses (id, class_id, name, description, flavor_text, selection_level, created_at) VALUES ('champion', 'fighter', 'Champion', 'A master of martial combat, skilled with a variety of weapons and armor', 'The archetypal Champion focuses on the development of raw physical power honed to deadly perfection.', 3, '2025-09-13 01:12:47');
INSERT INTO subclasses (id, class_id, name, description, flavor_text, selection_level, created_at) VALUES ('battle_master', 'fighter', 'Battle Master', 'Those who employ martial techniques passed down through generations', 'Battle Masters are students of combat, utilizing maneuvers and tactics to control the battlefield.', 3, '2025-09-13 01:12:47');
INSERT INTO subclasses (id, class_id, name, description, flavor_text, selection_level, created_at) VALUES ('eldritch_knight', 'fighter', 'Eldritch Knight', 'Fighters who combine martial mastery with careful study of magic', 'Eldritch Knights use magical techniques similar to those practiced by wizards, blending martial might and magic.', 3, '2025-09-13 01:12:47');
INSERT INTO subclasses (id, class_id, name, description, flavor_text, selection_level, created_at) VALUES ('berserker', 'barbarian', 'Path of the Berserker', 'For barbarians, rage is a means to an end—that end being violence', 'Berserkers channel their rage into brutal melee attacks, becoming unstoppable forces of destruction.', 3, '2025-09-13 01:12:47');
INSERT INTO subclasses (id, class_id, name, description, flavor_text, selection_level, created_at) VALUES ('totem_warrior', 'barbarian', 'Path of the Totem Warrior', 'Barbarians who accept a spirit animal as guide, protector, and inspiration', 'Totem Warriors draw strength from the spirits of animals, gaining their attributes in battle.', 3, '2025-09-13 01:12:47');
INSERT INTO subclasses (id, class_id, name, description, flavor_text, selection_level, created_at) VALUES ('arcane_trickster', 'rogue', 'Arcane Trickster', 'Rogues who enhance their skills with magic, learning wizard spells', 'Arcane Tricksters use enchantment and illusion magic to enhance their natural stealth and agility.', 3, '2025-09-13 01:12:47');
INSERT INTO subclasses (id, class_id, name, description, flavor_text, selection_level, created_at) VALUES ('evocation', 'wizard', 'School of Evocation', 'Wizards who focus on magic that creates powerful elemental effects', 'Evokers harness destructive magical energy, sculpting spells to protect allies while devastating foes.', 3, '2025-09-13 01:12:47');
INSERT INTO subclasses (id, class_id, name, description, flavor_text, selection_level, created_at) VALUES ('abjuration', 'wizard', 'School of Abjuration', 'Wizards specializing in protective magic and wards', 'Abjurers are masters of protective magic, creating powerful wards and barriers against harm.', 3, '2025-09-13 01:12:47');
INSERT INTO subclasses (id, class_id, name, description, flavor_text, selection_level, created_at) VALUES ('divination', 'wizard', 'School of Divination', 'Wizards who peer through time and fate to uncover secrets', 'Diviners can glimpse the future and use this knowledge to alter fate itself.', 3, '2025-09-13 01:12:47');
INSERT INTO subclasses (id, class_id, name, description, flavor_text, selection_level, created_at) VALUES ('life', 'cleric', 'Life Domain', 'Clerics who focus on healing and preserving life', 'Life domain clerics are blessed with powerful healing magic, mending wounds and restoring vitality.', 3, '2025-09-13 01:12:47');
INSERT INTO subclasses (id, class_id, name, description, flavor_text, selection_level, created_at) VALUES ('light', 'cleric', 'Light Domain', 'Clerics who wield the power of light and fire', 'Light domain clerics channel divine radiance to banish darkness and incinerate foes.', 3, '2025-09-13 01:12:47');
INSERT INTO subclasses (id, class_id, name, description, flavor_text, selection_level, created_at) VALUES ('war', 'cleric', 'War Domain', 'Clerics who bless warriors and inspire victory in battle', 'War domain clerics are blessed crusaders, channeling divine might in combat.', 3, '2025-09-13 01:12:47');
INSERT INTO subclasses (id, class_id, name, description, flavor_text, selection_level, created_at) VALUES ('gladiator', 'fighter', 'Gladiator', 'A crowd-pleasing arena warrior who thrives on spectacle', 'Gladiators are showmen as much as warriors, turning combat into performance art.', 3, '2025-09-12 17:14:45');
INSERT INTO subclass_features (id, subclass_id, level, feature_name, description, mechanics, action_type, uses_per_rest, rest_type, created_at) VALUES (1, 'champion', 3, 'Improved Critical', 'Your weapon attacks score a critical hit on a roll of 19 or 20', '{"critical_range_min": 19}', 'passive', NULL, NULL, '2025-09-12 07:46:32');
INSERT INTO subclass_features (id, subclass_id, level, feature_name, description, mechanics, action_type, uses_per_rest, rest_type, created_at) VALUES (2, 'champion', 7, 'Remarkable Athlete', 'Add half proficiency (round up) to STR, DEX, and CON checks without proficiency', '{"half_prof_physical": true}', 'passive', NULL, NULL, '2025-09-12 07:46:32');
INSERT INTO subclass_features (id, subclass_id, level, feature_name, description, mechanics, action_type, uses_per_rest, rest_type, created_at) VALUES (3, 'champion', 10, 'Additional Fighting Style', 'Choose a second Fighting Style', '{"additional_fighting_style": 1}', 'passive', NULL, NULL, '2025-09-12 07:46:32');
INSERT INTO subclass_features (id, subclass_id, level, feature_name, description, mechanics, action_type, uses_per_rest, rest_type, created_at) VALUES (4, 'champion', 10, 'Heroic Warrior', 'At start of turn, regain 5 + CON mod HP if below half HP', '{"regen_hp": "5+con"}', 'passive', NULL, NULL, '2025-09-12 07:46:32');
INSERT INTO subclass_features (id, subclass_id, level, feature_name, description, mechanics, action_type, uses_per_rest, rest_type, created_at) VALUES (5, 'champion', 15, 'Superior Critical', 'Your weapon attacks score a critical hit on a roll of 18-20', '{"critical_range_min": 18}', 'passive', NULL, NULL, '2025-09-12 07:46:32');
INSERT INTO subclass_features (id, subclass_id, level, feature_name, description, mechanics, action_type, uses_per_rest, rest_type, created_at) VALUES (6, 'champion', 18, 'Survivor', 'At start of turn, regain 10 + CON mod HP if below half HP', '{"regen_hp": "10+con"}', 'passive', NULL, NULL, '2025-09-12 07:46:32');
INSERT INTO subclass_features (id, subclass_id, level, feature_name, description, mechanics, action_type, uses_per_rest, rest_type, created_at) VALUES (7, 'gladiator', 3, 'Crowd Pleaser', 'When you score a critical hit, gain temp HP equal to your fighter level', '{"on_crit": "temp_hp_level"}', 'passive', NULL, NULL, '2025-09-12 07:46:32');
INSERT INTO subclass_features (id, subclass_id, level, feature_name, description, mechanics, action_type, uses_per_rest, rest_type, created_at) VALUES (8, 'gladiator', 3, 'Performance Fighter', 'Gain proficiency in Performance and Intimidation', '{"skills": ["performance", "intimidation"]}', 'passive', NULL, NULL, '2025-09-12 07:46:32');
INSERT INTO subclass_features (id, subclass_id, level, feature_name, description, mechanics, action_type, uses_per_rest, rest_type, created_at) VALUES (9, 'gladiator', 7, 'Arena Reflexes', 'You have advantage on initiative rolls and can draw/stow two weapons as part of your movement', '{"initiative_advantage": true, "quick_draw": true}', 'passive', NULL, NULL, '2025-09-12 07:46:32');
INSERT INTO subclass_features (id, subclass_id, level, feature_name, description, mechanics, action_type, uses_per_rest, rest_type, created_at) VALUES (10, 'gladiator', 10, 'Signature Move', 'Once per short rest, make a special attack that deals extra damage and can frighten', '{"damage_bonus": "2d6", "save_dc": "8+prof+str", "effect": "frightened"}', 'action', 1, 'short', '2025-09-12 07:46:32');
INSERT INTO subclass_features (id, subclass_id, level, feature_name, description, mechanics, action_type, uses_per_rest, rest_type, created_at) VALUES (11, 'gladiator', 15, 'Crowd Favorite', 'When below half HP, gain resistance to all damage except psychic', '{"bloodied_resistance": true}', 'passive', NULL, NULL, '2025-09-12 07:46:32');
INSERT INTO subclass_features (id, subclass_id, level, feature_name, description, mechanics, action_type, uses_per_rest, rest_type, created_at) VALUES (12, 'gladiator', 18, 'Champion of the Arena', 'Your Signature Move recharges on a 5-6 on d6 at start of turn', '{"signature_recharge": "5-6"}', 'passive', NULL, NULL, '2025-09-12 07:46:32');
INSERT INTO subclass_features (id, subclass_id, level, feature_name, description, mechanics, action_type, uses_per_rest, rest_type, created_at) VALUES (13, 'thief', 3, 'Fast Hands', 'Use thieves tools, Use Object action, or Sleight of Hand as bonus action', '{"bonus_action_options": ["thieves_tools", "use_object", "sleight_of_hand"]}', 'bonus_action', NULL, NULL, '2025-09-12 07:46:32');
INSERT INTO subclass_features (id, subclass_id, level, feature_name, description, mechanics, action_type, uses_per_rest, rest_type, created_at) VALUES (14, 'thief', 3, 'Second-Story Work', 'Climb at normal speed, running jump bonus equals DEX mod', '{"climb_speed": "normal", "jump_bonus": "dex"}', 'passive', NULL, NULL, '2025-09-12 07:46:32');
INSERT INTO subclass_features (id, subclass_id, level, feature_name, description, mechanics, action_type, uses_per_rest, rest_type, created_at) VALUES (15, 'thief', 9, 'Supreme Sneak', 'Advantage on Stealth checks if you move no more than half speed', '{"stealth_advantage_half_speed": true}', 'passive', NULL, NULL, '2025-09-12 07:46:32');
INSERT INTO subclass_features (id, subclass_id, level, feature_name, description, mechanics, action_type, uses_per_rest, rest_type, created_at) VALUES (16, 'thief', 13, 'Use Magic Device', 'Ignore class, race, and level requirements on magic items', '{"ignore_magic_requirements": true}', 'passive', NULL, NULL, '2025-09-12 07:46:32');
INSERT INTO subclass_features (id, subclass_id, level, feature_name, description, mechanics, action_type, uses_per_rest, rest_type, created_at) VALUES (17, 'thief', 17, 'Thief''s Reflexes', 'Take two turns in first round of combat (at initiative and initiative-10)', '{"double_first_turn": true}', 'passive', NULL, NULL, '2025-09-12 07:46:32');
INSERT INTO subclass_features (id, subclass_id, level, feature_name, description, mechanics, action_type, uses_per_rest, rest_type, created_at) VALUES (18, 'assassin', 3, 'Assassinate', 'Advantage on attacks vs creatures that haven''t acted; hits on surprised creatures are crits', '{"advantage_vs_slow": true, "auto_crit_surprised": true}', 'passive', NULL, NULL, '2025-09-12 07:46:32');
INSERT INTO subclass_features (id, subclass_id, level, feature_name, description, mechanics, action_type, uses_per_rest, rest_type, created_at) VALUES (19, 'assassin', 3, 'Assassin''s Tools', 'Gain proficiency with poisoner''s kit and disguise kit', '{"tool_proficiencies": ["poisoners_kit", "disguise_kit"]}', 'passive', NULL, NULL, '2025-09-12 07:46:32');
INSERT INTO subclass_features (id, subclass_id, level, feature_name, description, mechanics, action_type, uses_per_rest, rest_type, created_at) VALUES (20, 'assassin', 9, 'Infiltration Expertise', 'Create false identities with 7 days and 25gp', '{"create_identity": true}', 'passive', NULL, NULL, '2025-09-12 07:46:32');
INSERT INTO subclass_features (id, subclass_id, level, feature_name, description, mechanics, action_type, uses_per_rest, rest_type, created_at) VALUES (21, 'assassin', 13, 'Impostor', 'Perfectly mimic speech, writing, and behavior after 3 hours study', '{"perfect_mimicry": true}', 'passive', NULL, NULL, '2025-09-12 07:46:32');
INSERT INTO subclass_features (id, subclass_id, level, feature_name, description, mechanics, action_type, uses_per_rest, rest_type, created_at) VALUES (22, 'assassin', 17, 'Death Strike', 'When you hit a surprised creature, force CON save or double damage', '{"death_strike_dc": "8+prof+dex", "double_damage_on_fail": true}', 'passive', NULL, NULL, '2025-09-12 07:46:32');
